        description: "18 m. O shuyookh faydhaan dissuade os que estão ao redor da hostilidade. Criaturas dispostas na emanação ganham +2 de status em testes de Sociedade e Diplomacia. O shuyookh pode suprimir ou retomar a aura como ação livre. Se o shuyookh agir de modo hostil, a aura se desativa e não pode ser reativada por 1 hora. Quando qualquer outra criatura na aura age de modo hostil, precisa tentar uma salvaguarda de Vontade CD 35. Em sucesso, não é afetada e não precisa fazer a salvaguarda de novo por 1 hora; em falha, a ação atual é interrompida, assim como quaisquer outras ações hostis que tente por 1 rodada.",
