        actionType: "passive",
        frequency: "3 vezes por ano",
        description: "O shuyookh conduz um ritual Desejo em benefício de um mortal, sem custo nem conjuradores secundários. O resultado do shuyookh é um sucesso se ele passar num teste simples CD 5, ou uma falha se não passar. O shuyookh interpreta o desejo de modo a agradar o maior número de pessoas possível.",
