        description: "Um gennayn obtém sucesso automático com a ação Auxiliar em qualquer teste de Performance ou Diplomacia. A ação Auxiliar conta automaticamente como sucesso crítico ao ajudar na criação de uma arte nova ou de uma performance nova.",
