        description: "O shuyookh conduz um ritual Desejo em benefício de um mortal, sem custo nem conjuradores secundários. O resultado do shuyookh é um sucesso se ele passar num teste simples CD 5, ou uma falha se não passar. As visões do shuyookh sobre o futuro do sujeito informam como ele interpreta o desejo.",
