        description: "O sentido sísmico permite sentir vibrações no solo causadas por movimento. É um sentido impreciso com o alcance listado. Só funciona se a criatura e o alvo estiverem na mesma superfície, e só se o alvo estiver se movendo sobre ela (ou escavando através dela).",
