        description: "O bosque vivo pode se Esconder em ambientes naturais mesmo sem cobertura. Enquanto estiver Escondido, o sistema de raízes fica a salvo sob a terra, concedendo ao bosque um bônus de status de +3 à CA. Um acerto crítico racha essa camada protetora de terra, que se dispersa no vento e encerra o efeito.",
