        name: "Engolfar",
        originalName: "Engulf",
        actionType: "two",
        description: "Salvaguarda de Reflexos CD 22, 5d8 de dano de concussão, Escapar CD 20, Ruptura 10.\n Uma criatura Engolfada pelo bosque vivo também precisa tentar uma salvaguarda de Fortitude CD 22 ao ser sacudida entre os troncos finos e densos.\n Sucesso crítico: a criatura não é afetada.\n Sucesso: a criatura fica Atordoada 1.\n Falha: a criatura fica Atordoada 2.\n Falha crítica: a criatura fica Atordoada 4.\n A criatura Distancia até o dobro do Deslocamento e pode se mover pelo espaço de outras criaturas. Cada uma cujo espaço ela atravessa faz Reflexos com a CD listada. Em sucesso, escolhe ser empurrada para o lado ou ficar na esteira da criatura. Em falha, é engolfada: sofre o dano listado na hora e no fim de cada turno, fica Agarrada e Atrasada 1, e precisa prender a respiração ou começa a sufocar. Pode Escapar contra a CD listada. Só ataca a criatura que a engolfou com ataques desarmados ou armas de Carga leve ou menor; essa criatura fica Desprotegida contra esses ataques. Se a criatura sofrer dano perfurante ou cortante igual ou maior que o valor de Ruptura num único ataque ou magia, o alvo é libertado e pode respirar na hora.",
