        description: "18 m.\n A magnetita viva emite o tempo todo um campo magnético poderoso, alinhado de forma positiva ou negativa. Cada criatura na aura que empunhe uma arma metálica, vista armadura metálica ou seja feita parcial ou totalmente de metal sofre um efeito determinado pela polaridade atual da magnetita.\n Negativa: uma criatura afetada é empurrada 1,5 m para longe da magnetita no início de cada um dos turnos dela, e trata cada quadrado na aura como terreno difícil ao se mover para mais perto da magnetita. Objetos de metal desacompanhados na aura com Carga 2 ou menos são empurrados para imediatamente fora da aura.\n Positiva: uma criatura afetada é puxada 1,5 m na direção da magnetita no início de cada um dos turnos dela, e trata cada quadrado na aura como terreno difícil ao se afastar da magnetita. Objetos de metal desacompanhados na aura com Carga 2 ou menos são puxados para adjacentes à magnetita.",
