        description: "O mercurial assume a aparência de qualquer humanóide Pequeno ou Médio. Esta transformação permite detalhes significativos e pode reproduzir os traços de um indivíduo específico, mas o mercurial conserva um aspecto brilhante de metal líquido que torna a transformação inadequada como disfarce, a menos que esteja se passando por outro mercurial. Isso não muda o Deslocamento nem os bônus de ataque e dano dos Golpes, mas permite transformar os membros em ferramentas ou armas corpo a corpo de metal, o que pode alterar o tipo de dano causado pelos Golpes.\n A criatura assume outra forma. As estatísticas em geral não mudam, salvo o que a habilidade listar.",
