        name: "Forma de Barreira",
        originalName: "Barrier Form",
        actionType: "three",
        requirements: "O enxame de nanoestilhaços está em forma de enxame.",
        description: "O enxame de nanoestilhaços forma uma parede sólida contínua de 15 cm de espessura, com até 18 m de comprimento e 3 m de altura, originada de qualquer quadrado do espaço atual. A parede pode seguir qualquer trajeto, com cada 1,5 m colocado na borda entre quadrados. Não precisa ficar na vertical, de modo que pode formar uma ponte ou um lance de escadas, por exemplo. A parede precisa ser formada num espaço aberto ininterrupto cujas bordas não atravessem criaturas nem objetos.\n Uma seção única de 1,5 m por 1,5 m da parede pode ser destruída ao sofrer 18 pontos de dano, o que também reduz os PV totais do enxame. Um enxame de nanoestilhaços não pode ficar Caído nem ser movido à força enquanto estiver na forma de barreira, nem pode se mover voluntariamente. Um enxame de nanoestilhaços na forma de barreira pode originar ataques de gavinha a partir de qualquer quadrado da parede.",
