        id: "nanoshard-swarm-battle-form",
        name: "Forma de Batalha",
        originalName: "Battle Form",
        actionType: "two",
        requirements: "O enxame de nanoestilhaços está em forma de enxame.",
        description: "O enxame de nanoestilhaços se condensa numa forma Enorme que lembra um humanóide ou uma fera e pode empunhar itens. Na forma de batalha, o Deslocamento é 4,5 m, fica Desajeitado 1 e tem o seguinte Golpe.\n Corpo a corpo 1 membro (alcance 6 m), Dano 4d8+9 de concussão",
