        description: "1,5 m.\n O devoraminério vaza o tempo todo minúsculos fragmentos de ferrugem parcialmente digerida no ar ao redor. Qualquer criatura que termine o turno na aura sofre 2d6 de dano de ácido com uma salvaguarda básica de Reflexos CD 27. Uma criatura que falhe criticamente também fica Enjoada 1.",
