        description: "O cervo sacode as placas de madeira ao longo do corpo num estrépito ensurdecedor que faz os padrões pintados dançarem. Todas as criaturas a até 18 m do cervo pintado que possam vê-lo ou ouvi-lo precisam tentar uma salvaguarda de Vontade CD 28; uma criatura Agarrada pelo cervo sofre penalidade de circunstância de –4 na salvaguarda. Independentemente do resultado, cada criatura fica temporariamente imune por 1 hora.\n Sucesso crítico: a criatura não é afetada.\n Sucesso: a criatura fica Fascinada pelo cervo pintado por 1 rodada.\n Falha: a criatura fica Atordoada 2 e Fascinada pelo cervo pintado enquanto estiver atordoada.\n Falha crítica: como a falha, exceto Atordoada 4.",
