    abilities: [
      {
        id: "pelegox-cube-telepathy",
        name: "Telepatia 9 m",
        originalName: "Telepathy 30 feet",
        actionType: "passive",
        description: "A criatura se comunica mentalmente com qualquer criatura no alcance que compartilhe um idioma.",
      },
      {
        id: "pelegox-cube-metalsense",
        name: "Sentido de Metal",
        originalName: "Metalsense",
        actionType: "passive",
        description: "Um cubo de pelegox pode sentir criaturas e objetos de metal como um sentido impreciso.",
      },
      {
        id: "pelegox-cube-troop-defenses",
        name: "Defesas de Tropa",
        originalName: "Troop Defenses",
        actionType: "passive",
        description: "Tropas são compostas de muitos indivíduos, representadas por quatro “segmentos” no mapa. Cada segmento tem 3 m de lado e a altura dos membros da tropa. Os segmentos precisam permanecer contíguos: cada um deve compartilhar pelo menos 1,5 m de uma aresta com outro — adjacência só na diagonal não basta. Flanqueamento, cobertura e similares usam o centro de qualquer segmento.\n\nA tropa tem dois limiares de PV na entrada de PV e perde segmentos ao cruzá-los. Em geral o limiar alto é 2/3 dos PV máximos e o baixo é 1/3. Ao cair abaixo do limiar alto, perde um segmento (restam três, 12 quadrados) e aquele limiar vira o novo máximo de PV. Isso se repete ao cair abaixo do limiar baixo (restam dois segmentos, 8 quadrados). A 0 PV, a tropa se dispersa: os poucos restantes se rendem, fogem ou são facilmente despachados, a critério do Mestre. Em geral quem fez a tropa perder o segmento escolhe qual remover; o Mestre decide se nenhuma criatura específica foi responsável. Para restaurar segmentos e PV máximos, a tropa precisa gastar tempo de downtime em tratamento prolongado dos feridos ou recrutar novos membros.\n\nTropas em geral são imunes a efeitos sem dano que alvejem uma única criatura, como Encantar ou Intimidar. Uma habilidade que possa alvejar 5 ou mais criaturas pode alvejar um segmento inteiro; dois segmentos se puder alvejar 10 ou mais; a tropa inteira se puder alvejar 20 ou mais. Uma habilidade que afete todas as criaturas num alcance afeta todos os segmentos nesse alcance (testes e salvaguardas separados por segmento). Exemplo: Encantar de 8º círculo (10 alvos) afeta dois segmentos; Intimidar todas as criaturas a até 9 m afeta todos os segmentos totalmente nesse alcance. Um efeito sem dano que impediria um segmento de agir, o faria fugir ou o impediria de funcionar com a tropa por 1 rodada ou mais remove o segmento por completo: a tropa perde os PV necessários para o próximo limiar. Se a habilidade causa dano e um efeito sem dano, aplique o dano e depois o restante.",
      },
      {
        id: "pelegox-cube-entrancing-shapes",
        name: "Formas Hipnotizantes",
        originalName: "Entrancing Shapes",
        actionType: "two",
        description: "O cubo de pelegox se desloca depressa, criando um espetáculo de padrões geométricos aparentemente impossíveis. Criaturas num cone de 18 m sofrem 9d6 de dano mental (salvaguarda básica de Vontade CD 29). Uma criatura que falhe também fica Fascinada pelo cubo de pelegox e Embotada 1 por 1 minuto.",
      },
      {
        id: "pelegox-cube-scrambled-strike",
        name: "Golpe Embaralhado",
        originalName: "Scrambled Strike",
        actionType: "one",
        frequency: "1 vez por rodada",
        description: "1 a 3.\n Efeito: o cubo de pelegox se rearranja para criar espinhos salientes, atacando cada inimigo a até 3 m (salvaguarda básica de Reflexos CD 27). O dano depende do número de ações.\n 1: 2d6 de dano perfurante\n 2: 3d6 de dano perfurante\n 3: 5d6 de dano perfurante",
      },
      {
        id: "pelegox-cube-shard-volley",
        name: "Saraivada de Estilhaços",
        originalName: "Shard Volley",
        actionType: "two",
        description: "O cubo de pelegox magnetiza fragmentos de metal à distância. Isto é uma explosão de 3 m a até 9 m que causa 2d6 de dano perfurante (salvaguarda básica de Reflexos CD 27). Quando a tropa é reduzida a 2 segmentos ou menos, esta área diminui para uma explosão de 1,5 m.",
      },
      {
        id: "pelegox-cube-troop-movement",
        name: "Movimento de Tropa",
        originalName: "Troop Movement",
        actionType: "passive",
        description: "Quando a tropa se move, você move um dos segmentos e os outros seguem. Ao fim do movimento, pode agrupar os demais adjacentes ao que moveu como quiser, desde que nenhum se desloque mais do que o segmento que liderou. Se não mover a tropa, pode em vez disso rearranjar todos os segmentos, desde que um permaneça no lugar.",
      },
    ],
    summary: "Tropa de cubos de metal. A formação é geometria letal.",
