        actionType: "two",
        description: "O draco-estalo sopra uma rajada de pólen num cone de 12 m. Criaturas atingidas pela rajada devem passar numa salvaguarda de Reflexos CD 25 ou são expostas ao pólen de draco-estalo.\nO draco-estalo não pode usar Jato de Pólen de novo por 1d6 rodadas.",
