        description: "Os gêmeos de Rowan fazem um Golpe de florete, seguido de dois Golpes de punho, todos contra o mesmo alvo. Esses ataques contam para a penalidade de ataques múltiplos dos gêmeos, mas a penalidade só aumenta depois que os gêmeos tiverem feito os ataques.",
