        description: "1 vez por dia, os gêmeos de Rowan podem golpear o chão com a espada, liberando uma explosão de 9 m de energia vital centrada nos gêmeos que causa 14d6 de vitalidade (salvaguarda básica de Fortitude CD 30); os gêmeos de Rowan são imunes. A área afetada pela explosão então se torna terreno extremamente difícil, conforme vida vegetal vibrante rompe o solo.",
