        description: "O shuyookh escolhe qualquer número de criaturas afetadas pelo campo magnético e move cada alvo 3 m numa direção que a zuhra escolher. Cada alvo pode resistir a ser movido se passar numa salvaguarda de Fortitude CD 32.",
