        description: "O shuyookh arremessa eletromagneticamente sucata de metal afiada como lâminas. Cada criatura numa emanação de 9 m sofre 8d6 de cortante e 3d12 de eletricidade, com salvaguarda básica de Fortitude CD 32.\nO campo magnético do shuyookh fica desativado por 1d4 rodadas.",
