        description: "O shuyookh conduz um ritual Desejo em benefício de um mortal, sem custo nem conjuradores secundários. O resultado do shuyookh é um sucesso se passar num teste simples CD 5, ou uma falha se não passar. O shuyookh tenta cumprir o desejo de um modo que crie um benefício instável ou impermanente.",
