        description: "Quando um anemos conjura um ritual, executa sozinho todos os aspectos, ordenando aos ventos que completem todos os componentes. O anemos deve cumprir quaisquer requisitos dos conjuradores adicionais do ritual e tentar os testes que esses conjuradores fariam. Além disso, os anemoi conjuram rituais mais depressa do que o normal. Se um ritual tiver tempo de conjuração medido em dias, podem conjurá-lo num número igual de horas.",
