        actionType: "two",
        description: "O anemos arremessa um raio e então se torna um vento que o leva num instante até o local do raio para atacar de novo. Ele faz um Golpe à distância de raio contra uma criatura no primeiro incremento de alcance, teleporta-se até o local da criatura como uma lufada de vento, segura o raio arremessado e faz um Golpe corpo a corpo de raio contra uma criatura no alcance. A penalidade de ataques múltiplos só aumenta depois que os dois ataques tiverem sido feitos.",
