        description: "A criatura recupera o número listado de PV no início de cada turno. A condição Morrendo nunca passa de Morrendo 3 enquanto a regeneração estiver ativa. Porém, se sofrer dano de um tipo listado, a regeneração desliga até o fim do próximo turno. Desligue a regeneração antes de aplicar qualquer dano do tipo listado, pois esse dano pode matar a criatura ao levá-la a Morrendo 4.",
