        description: "24 m. Os ventos ficam turbulentos para quem ousar voar no mesmo espaço que um anemos, mas tomam o cuidado de nunca ferir nem atrapalhar o próprio pastor. O ar na emanação é terreno difícil para criaturas que estejam Voando e não tenham o traço ar. Enquanto a aura estiver ativa, o anemos não pode ser afetado por ar ambiental nem por efeitos climáticos, a menos que escolha ser.",
