        description: "Soldados de fuligem que servem o outro Senhor do Fogo, o Rei Lambente Atreia, são cobertos de brasas brilhantes em vez de carvão negro.\nQuando os soldados de fuligem são reduzidos por um limiar de PV ou caem a 0 PV, os soldados destruídos desmoronam numa nuvem de fumaça carregada de cinzas numa explosão de 6 m centrada nos soldados de fuligem. Qualquer criatura na área deve tentar uma salvaguarda de Reflexos CD 29. Em uma falha, por 1 minuto essa criatura fica Ofuscada e sua invisibilidade é anulada.",
